using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace GpuPro.Windows;
public sealed partial class MainWindow {
 void BuildFeedbackActions(){body.Children.Add(Text("Gere o arquivo, revise e envie manualmente. Não há upload automático. Dados de terceiros são referências não verificadas e nunca são aplicados como overclock."));body.Children.Add(Button("Gerar feedback · revisar e salvar JSON",async()=>{try{var result=await Data(new(){["operation"]="feedback"});var feedback=result["feedback"]!.AsObject();var view=new TextBox{Text=feedback.ToJsonString(new JsonSerializerOptions{WriteIndented=true}),IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinWidth=560,MaxHeight=500};var dialog=new ContentDialog{XamlRoot=Root.XamlRoot,Title="Revisar feedback",Content=view,PrimaryButtonText="Salvar JSON",CloseButtonText="Cancelar"};if(await dialog.ShowAsync()==ContentDialogResult.Primary)await SaveJsonFile(feedback,"GPU-PRO-feedback");}catch(Exception e){TestError(e);}}));body.Children.Add(Button("Importar feedback de amigos",async()=>{try{var picker=new global::Windows.Storage.Pickers.FileOpenPicker();WinRT.Interop.InitializeWithWindow.Initialize(picker,hwnd);picker.FileTypeFilter.Add(".json");var file=await picker.PickSingleFileAsync();if(file==null)return;var info=new FileInfo(file.Path);if(info.Length>16*1024*1024)throw new InvalidDataException("Limite de 16 MiB excedido.");var feedback=JsonNode.Parse(File.ReadAllText(file.Path))?.AsObject()??throw new InvalidDataException("JSON inválido");var result=await Data(new(){["operation"]="import",["feedback"]=feedback});Record("Referências importadas: "+result["imported"]+" · não verificadas");}catch(Exception e){TestError(e);}}));body.Children.Add(Button("Consultar banco importado · não verificado",async()=>{try{var response=await Data(new(){["operation"]="references"});var content=new TextBox{Text=response["records"]!.ToJsonString(new JsonSerializerOptions{WriteIndented=true}),IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinWidth=560,MaxHeight=500};await new ContentDialog{XamlRoot=Root.XamlRoot,Title="Referências não verificadas",Content=content,CloseButtonText="Fechar"}.ShowAsync();}catch(Exception e){TestError(e);}}));body.Children.Add(Button("Selecionar FFmpeg instalado",async()=>{try{var picker=new global::Windows.Storage.Pickers.FileOpenPicker();WinRT.Interop.InitializeWithWindow.Initialize(picker,hwnd);picker.FileTypeFilter.Add(".exe");var file=await picker.PickSingleFileAsync();if(file==null)return;if(!Path.GetFileName(file.Path).Equals("ffmpeg.exe",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Selecione ffmpeg.exe.");Directory.CreateDirectory(dataRoot);File.WriteAllText(Path.Combine(dataRoot,"ffmpeg-path.txt"),Path.GetDirectoryName(file.Path));Record("FFmpeg configurado para os testes de vídeo: "+file.Path);}catch(Exception e){TestError(e);}}));var motion=new CheckBox{Content="Animar neon dos cards",IsChecked=NeonCard.Motion};motion.Checked+=(s,e)=>NeonCard.Motion=true;motion.Unchecked+=(s,e)=>NeonCard.Motion=false;body.Children.Add(motion);}
 async Task SaveJsonFile(JsonNode data,string name){var picker=new global::Windows.Storage.Pickers.FileSavePicker{SuggestedFileName=name};WinRT.Interop.InitializeWithWindow.Initialize(picker,hwnd);picker.FileTypeChoices.Add("JSON",new List<string>{".json"});var file=await picker.PickSaveFileAsync();if(file!=null)File.WriteAllText(file.Path,data.ToJsonString(new JsonSerializerOptions{WriteIndented=true}));}
 Border? reportCard;
 async Task ExportReportImage(){try{if(reportCard==null||selectedReport==null)throw new InvalidOperationException("Selecione um resultado no Benchmark.");var picker=new global::Windows.Storage.Pickers.FileSavePicker{SuggestedFileName="GPU-PRO-resultado"};WinRT.Interop.InitializeWithWindow.Initialize(picker,hwnd);picker.FileTypeChoices.Add("PNG",new List<string>{".png"});picker.FileTypeChoices.Add("JPEG",new List<string>{".jpg"});var file=await picker.PickSaveFileAsync();if(file==null)return;var image=new Microsoft.UI.Xaml.Media.Imaging.RenderTargetBitmap();await image.RenderAsync(reportCard);var buffer=await image.GetPixelsAsync();var pixels=new byte[buffer.Length];using(var reader=global::Windows.Storage.Streams.DataReader.FromBuffer(buffer))reader.ReadBytes(pixels);using var stream=await file.OpenAsync(global::Windows.Storage.FileAccessMode.ReadWrite);var format=Path.GetExtension(file.Path)==".jpg"?global::Windows.Graphics.Imaging.BitmapEncoder.JpegEncoderId:global::Windows.Graphics.Imaging.BitmapEncoder.PngEncoderId;var encoder=await global::Windows.Graphics.Imaging.BitmapEncoder.CreateAsync(format,stream);encoder.SetPixelData(global::Windows.Graphics.Imaging.BitmapPixelFormat.Bgra8,global::Windows.Graphics.Imaging.BitmapAlphaMode.Premultiplied,(uint)image.PixelWidth,(uint)image.PixelHeight,96,96,pixels);await encoder.FlushAsync();}catch(Exception e){TestError(e);}}
}
